    const p = evidence.accepted_passages.find(p => p.id === f.passage_id && p.relevance === 'direct');
    if (!p || !p.observation) fail('no accepted direct numeric observation');
    for (const k of ['subject','value','unit','year','measure','scope']) if (f[k] !== p.observation[k]) fail('finding ' + k + ' differs from evidence');
